sqlite3 /app/oewn.sqlite "
SELECT 'dup_wordid_in_words', COUNT(*) FROM (SELECT wordid FROM words GROUP BY wordid HAVING COUNT(*)>1);
SELECT 'orphan_sense_wordid', COUNT(*) FROM senses s LEFT JOIN words w ON s.wordid=w.wordid WHERE w.wordid IS NULL;
SELECT 'orphan_sense_synsetid', COUNT(*) FROM senses s LEFT JOIN synsets y ON s.synsetid=y.synsetid WHERE y.synsetid IS NULL;
SELECT 'null_wordid_senses', COUNT(*) FROM senses WHERE wordid IS NULL;
SELECT 'null_synsetid_senses', COUNT(*) FROM senses WHERE synsetid IS NULL;
SELECT 'null_wordid_words', COUNT(*) FROM words WHERE wordid IS NULL;
SELECT 'null_synsetid_synsets', COUNT(*) FROM synsets WHERE synsetid IS NULL;
SELECT 'null_domainid_synsets', COUNT(*) FROM synsets WHERE domainid IS NULL;
SELECT 'null_posid_synsets', COUNT(*) FROM synsets WHERE posid IS NULL;
"
